const x = $json.body ?? $json;
const allowed = ['notice','deadline','event','resource'];
const type = String(x.type || '');
const title = String(x.title || '').trim();
const details = String(x.details || '').trim();
if (!allowed.includes(type)) throw new Error('Unsupported request type');
if (title.length < 3 || title.length > 160) throw new Error('Title must be 3-160 characters');
if (details.length < 3 || details.length > 1200) throw new Error('Details must be 3-1200 characters');
const category = type === 'event' ? 'event' : (type === 'deadline' ? 'academic' : 'general');
return [{json:{type,title,details,audience:String(x.audience || 'AI & DS students').slice(0,80),date:String(x.date || '').slice(0,30),category,status:'pending_review',approved:false,receivedAt:new Date().toISOString()}}];
